-- Global Rebrand & Clipboard
pcall(function()
    local d = "https://discord.gg/bq54xU98gW"
    if setclipboard then setclipboard(d)
    elseif toclipboard then toclipboard(d)
    elseif syn and syn.write_clipboard then syn.write_clipboard(d) end
