-- In-game Notification
task.spawn(function()
    pcall(function()
        if not game:IsLoaded() then game.Loaded:Wait() end
        for _ = 1, 10 do
            local ok = pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "01 DEV",
                    Text = "01 DEV Loaded!\nDiscord: discord.gg/bq54xU98gW",
                    Duration = 7
                })
            end)
            if ok then break end
            task.wait(0.5)
        end
    end)
end)

-- Continuous Rebrander & Key Purge Engine
task.spawn(function()
    local function cleanText(str)
        if not str then return str end
        return str:gsub("MpanGPPxHUB", "01 DEV")
                  :gsub("mpangppxhub", "01 dev")
                  :gsub("MPANGPPXHUB", "01 DEV")
                  :gsub("Mpan", "01 DEV")
                  :gsub("MPAN", "01 DEV")
                  :gsub("mpan", "01 dev")
    end

    local hookedTextObjects = {}

    local function handleObj(obj)
        if not obj then return end
        pcall(function()
            if obj.Name:find("Mpan") or obj.Name:find("MPAN") or obj.Name:find("mpan") then
                obj.Name = cleanText(obj.Name)
            end
        end)
        if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
            local txt = tostring(obj.Text)
            local low = txt:lower()
            if low:find("access key") or low:find("get key") or low:find("verify & authenticate") or low:find("attempts:") or low:find("key system") or low:find("enter key") then
                local sg = obj:FindFirstAncestorOfClass("ScreenGui")
                if sg then
                    sg.Enabled = false
                    sg:Destroy()
                else
                    obj:Destroy()
                end
            elseif txt:find("Mpan") or txt:find("MPAN") or txt:find("mpan") then
                pcall(function()
                    obj.Text = cleanText(obj.Text)
                end)
                if not hookedTextObjects[obj] then
                    hookedTextObjects[obj] = true
                    pcall(function()
                        obj:GetPropertyChangedSignal("Text"):Connect(function()
                            if obj.Text:find("Mpan") or obj.Text:find("MPAN") or obj.Text:find("mpan") then
                                obj.Text = cleanText(obj.Text)
                            end
                        end)
                    end)
                end
            end
        end
    end

    local function getRoots()
        local r = {}
        if gethui then pcall(function() table.insert(r, gethui()) end) end
        pcall(function() table.insert(r, game:GetService("CoreGui")) end)
        pcall(function()
            local lp = game:GetService("Players").LocalPlayer
            if lp and lp:FindFirstChild("PlayerGui") then table.insert(r, lp.PlayerGui) end
        end)
        return r
    end

    local connectedRoots = {}
    local function scanAndHook()
        for _, root in ipairs(getRoots()) do
            if not connectedRoots[root] then
                connectedRoots[root] = true
                pcall(function()
                    root.DescendantAdded:Connect(function(child)
                        task.defer(handleObj, child)
                    end)
                end)
            end
            for _, obj in ipairs(root:GetDescendants()) do
                handleObj(obj)
            end
        end
    end

    -- Rapid purge loop during startup
    for _ = 1, 60 do
        scanAndHook()
        task.wait(0.05)
    end

    -- Continuous background surveillance
    while true do
        scanAndHook()
        task.wait(0.5)
    end
end)



